/* Preserve the existing ABI; localize only identified implementation exports. */
{
  global:
    *;
  local:
    /* Localize identified duplicate implementation classes and templates. */
    extern "C++" {
      std::__h::basic_*buf?char?*?::*;
      vtable?for?std::__h::*;
      VTT?for?std::__h::*;
      construction?vtable?for?std::__h::*;
      std::__h::__*;
      ark::ClassHelper::PRIMITIVE_RUNTIME_NAMES;
      guard?variable?for?ark::ClassHelper::PRIMITIVE_RUNTIME_NAMES;
      vtable?for?ark::BitMemoryRegion?unsigned?char?const?;
      vtable?for?ark::BitMemoryStreamIn;
      vtable?for?ark::PandArg?bool?*;
      vtable?for?ark::PandArg?unsigned?int?*;
      vtable?for?ark::PandArg?unsigned?long?*;
      vtable?for?ark::PandArg?std::__h::basic_string?char?*;
      vtable?for?ark::PandArg?std::__h::vector?std::__h::basic_string?char?*;
      vtable?for?ark::PandArgBase;
      vtable?for?ark::PandArgCompound;
      vtable?for?ark::TaskRunner?*?;
      vtable?for?ark::compiler::BackgroundCompilerTaskRunner;
      vtable?for?ark::compiler::CodeInfo;
      vtable?for?ark::compiler::InPlaceCompilerTaskRunner;
      vtable?for?ark::compiler::ScopedTmpReg;
      vtable?for?ark::compiler::ScopedTmpRegImpl?*?;
      vtable?for?ark::os::Error;
      vtable?for?ark::os::mem::MapRange?*;
    };
    /* Keep compiler's implementation local; libarkencoder exports this API. */
    extern "C++" {
      ark::compiler::Encoder::*;
      vtable?for?ark::compiler::Encoder;
    };
    /* CRT entry points are reached through DT_INIT / DT_FINI. */
    _init;
    _fini;
};
